    examples: [
      {"title": "Две расстановки областей и оба результата разбора", "code": "fn longest<'a>(a: &'a str, b: &'a str) -> &'a str {\n    if a.len() >= b.len() { a } else { b }\n}\n\nstruct RecordView<'a> {\n    field: &'a str,\n}\n\nfn parse_borrowed(line: &str) -> RecordView<'_> {\n    RecordView {\n        field: line.split_once(':').map_or(line, |(_, field)| field),\n    }\n}\n\nfn parse_owned(line: &str) -> String {\n    parse_borrowed(line).field.to_owned()\n}\n\nfn main() {\n    let outer = String::from(\"lengthy\");\n    {\n        let inner = String::from(\"tiny\");\n        let result = longest(&outer, &inner);\n        assert_eq!(result, \"lengthy\");\n        // Использование результата заканчивается внутри блока.\n    }\n\n    let other = String::from(\"brief\");\n    let result;\n    {\n        let temporary_binding = &other;\n        result = longest(&outer, temporary_binding);\n    }\n    // Исчезла переменная ссылки, но не источник other.\n    assert_eq!(result, \"lengthy\");\n\n    let owned;\n    {\n        let line = String::from(\"kind:warning\");\n        let view = parse_borrowed(&line);\n        assert_eq!(view.field, \"warning\");\n        owned = parse_owned(&line);\n    }\n    assert_eq!(owned, \"warning\");\n    println!(\"lifetime checks passed\");\n}\n\n// Ожидаемый вывод:\n// lifetime checks passed", "explanation": "Результат применим, пока живы оба потенциальных источника; владеющий вариант от заимствованного отличает договор."},
      {"title": "Использование за границей источника", "code": "fn longest<'a>(a: &'a str, b: &'a str) -> &'a str {\n    if a.len() >= b.len() { a } else { b }\n}\n\nfn main() {\n    let outer = String::from(\"lengthy\");\n    let result;\n    {\n        let inner = String::from(\"tiny\");\n        result = longest(&outer, &inner);\n    }\n    println!(\"{result}\");\n}", "explanation": "E0597: время жизни `inner` недостаточно, даже если человеку очевиден выбор `outer`."},
      {"title": "Ссылка на локальное значение", "code": "fn field<'a>() -> &'a str {\n    let local = String::from(\"warning\");\n    &local\n}\n\nfn main() {}", "explanation": "E0515: аннотация не создаёт владельца и не продлевает жизнь локального `String`."},
    ],
